catalog_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {
	if (isLoading || newValue == '') {
		return;
	}
	g_form.getReference('new_owner', function (user) {
		if (user) {
			g_form.showFieldMsg('new_owner', 'Validating user ' + user.name + ' exists in SailPoint... Please Wait', 'info');
			g_form.setDisabled('new_owner', true);
			var filter = 'email eq "' + user.email + '"';

			var ga_identity = new GlideAjax('XalientGlideAjaxHelper');
			ga_identity.addParam('sysparm_name', 'getIdentity');
			ga_identity.addParam('sysparm_filter', filter);
			ga_identity.getXMLAnswer(function (response) {
				var identity_response = JSON.parse(response);
				g_form.hideFieldMsg('new_owner');
				if (identity_response.length == 0) {
					g_form.showFieldMsg('new_owner', 'Unable to find a record for ' + user.name + ' in SailPoint. Please choose another user', 'error');
				}
				else {
					g_form.hideFieldMsg('new_owner');
					g_form.setValue('new_owner_identity_id',identity_response[0].id);
				}

			});
			g_form.setDisabled('new_owner', false);
		}
	});
}
